import { createRequire } from 'node:module';
const require = createRequire(process.argv[2] + '/package.json');
const { chromium } = require('@playwright/test');
const b = await chromium.launch();
const c = await b.newContext();
await c.addCookies([
  { name: 'cookieconsent_status', value: 'dismiss', domain: 'localhost', path: '/' },
  { name: 'language', value: 'en', domain: 'localhost', path: '/' },
]);
const p = await c.newPage();
await p.goto('http://localhost:3000/#/search');
await p.locator('mat-card').first().waitFor();
console.log(await p.locator('app-search-result').evaluate(e => e.outerHTML.slice(0, 1500)));
console.log('----');
console.log(await p.locator('app-mat-search-bar').evaluate(e => e.outerHTML.slice(0, 2000)));
await p.locator('#searchQuery').click();
await p.keyboard.type('xyz123');
await p.keyboard.press('Enter');
await p.waitForTimeout(1500);
console.log('----', p.url());
console.log(await p.locator('app-search-result').evaluate(e => e.innerText.slice(0, 500)));
console.log(await p.locator('app-search-result').evaluate(e => e.outerHTML.slice(0, 2500)));
await b.close();
